const today = new Date(now.getTime());
today.setHours(0,0,0,0); // Node-RED server local timezone; set TZ explicitly.
const start = r.window === "today" ? today.getTime()
            : r.window === "week" ? now.getTime() - 7*24*60*60*1000 : null;
